export function normalizeNeighborhood(cityKey: string, rawNeighborhood?: string): string {
  if (!cityKey) return rawNeighborhood || 'Center';
  const lowerCity = cityKey.toLowerCase();
  const profile = Object.values(TOURISTIC_PROFILES).find(p => 
    p.id?.toLowerCase() === lowerCity || 
    p.name.toLowerCase() === lowerCity ||
    p.name.toLowerCase().replace(/[^a-z0-9]/g, '_') === lowerCity.replace(/[^a-z0-9]/g, '_')
  );
  if (!profile) return rawNeighborhood || 'Center';

  const official = [
    ...(profile.touristicNeighborhoods || []),
    ...(profile.midNeighborhoods || []),
    ...(profile.lowNeighborhoods || [])
  ];

  if (!rawNeighborhood) return official[0] || 'Center';

  const exact = official.find(o => o.toLowerCase() === rawNeighborhood.toLowerCase());
  if (exact) return exact;

  const lowerRaw = rawNeighborhood.toLowerCase();
  const sub = official.find(o => lowerRaw.includes(o.toLowerCase()) || o.toLowerCase().includes(lowerRaw));
  if (sub) return sub;

  if (lowerRaw.includes('marina') || lowerRaw.includes('port')) {
    const m = official.find(o => o.toLowerCase().includes('marina') || o.toLowerCase().includes('port'));
    if (m) return m;
  }
  if (lowerRaw.includes('beach') || lowerRaw.includes('corniche') || lowerRaw.includes('balneaire') || lowerRaw.includes('touristique')) {
    const b = official.find(o => o.toLowerCase().includes('balneaire') || o.toLowerCase().includes('beach'));
    if (b) return b;
  }
  if (lowerRaw.includes('talborjt')) {
    const t = official.find(o => o.toLowerCase().includes('talborjt'));
    if (t) return t;
  }
  if (lowerRaw.includes('founty') || lowerRaw.includes('palmiers')) {
    const f = official.find(o => o.toLowerCase().includes('founty'));
    if (f) return f;
  }
  if (lowerRaw.includes('centre') || lowerRaw.includes('ville') || lowerRaw.includes('center')) {
    const c = official.find(o => o.toLowerCase().includes('ville') || o.toLowerCase().includes('centre') || o.toLowerCase().includes('charaf'));
    if (c) return c;
  }

  return profile.touristicNeighborhoods?.[0] || official[0] || rawNeighborhood;
}

export function getListings(city?: string, focus?: string): any[] {
  if (!city || typeof city !== 'string') return [];

  if (!focus) {
    const focusCategories = ['eat', 'sleep', 'things', 'shop'];
    const all = focusCategories.flatMap(f => getListings(city, f));
    const seen = new Set();
    return all.filter(item => {
      if (!item) return false;
      const key = item.id || item.title || item.name;
      if (!key) return true;
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    });
  }

  let normalizedFocus = (focus || '').toLowerCase();
  if (normalizedFocus === 'activities' || normalizedFocus === 'visit' || normalizedFocus === 'things-to-do' || normalizedFocus === 'experiences') {
    normalizedFocus = 'things';
  } else if (normalizedFocus === 'food') {
    normalizedFocus = 'eat';
  } else if (normalizedFocus === 'shopping') {
    normalizedFocus = 'shop';
  }
  
  const cityKey = city.toLowerCase();
  const subDestinations = (hierarchy as any)[cityKey] || [];
  
  const keysToFetch = [cityKey, ...subDestinations].map(c => `${c}-${normalizedFocus}`);
  
  const listings = keysToFetch.flatMap(key => listingsRegistry[key] || []);
  
  return listings
    .filter(Boolean)
    .map(item => {
      const enriched = enrichListingTags({
        ...item,
        title: item.title || item.name
      });
      return {
        ...enriched,
        neighborhood: normalizeNeighborhood(city, enriched.neighborhood)
      };
    });
}
